const items = Array.isArray($json) ? $json.slice(1, 4) : [];
return items.map(job => ({
  json: {
    source: 'RemoteOK',
    title: job.position || 'Software Engineer',
    company: job.company || 'Unknown',
    url: job.url || 'https://remoteok.com',
    salary: job.salary_min ? `$${job.salary_min.toLocaleString()} - $${job.salary_max.toLocaleString()}` : 'Competitive',
    location: job.location || 'Remote',
    tags: job.tags || []
  }
}));

const jobs = $json.jobs || [];
return jobs.slice(0, 3).map(job => ({
  json: {
    source: 'Jobicy',
    title: job.jobTitle,
    company: job.companyName,
    url: job.url,
    salary: job.annualSalaryMin ? `$${job.annualSalaryMin}` : 'Negotiable',
    location: job.jobGeo || 'Global Remote',
    tags: [job.jobLevel, job.jobIndustry].filter(Boolean)
  }
}));

const items = $json.items || [];
return items.map(issue => ({
  json: {
    source: 'GitHub Bounties',
    title: issue.title,
    company: issue.repository_url.split('/').slice(-2).join('/'),
    url: issue.html_url,
    salary: 'Direct Bounty Payout',
    location: 'Open Source',
    tags: issue.labels.map(l => l.name)
  }
}));

const linkedInHighPriority = [
  {
    source: 'LinkedIn Jobs',
    title: 'Solutions Architect (IoT, IIoT, Edge & Cloud)',
    company: 'Hexaware Technologies',
    url: 'https://www.linkedin.com/jobs/view/4483630397/',
    salary: 'Enterprise Package (Dubai)',
    location: 'Dubai, UAE (On-site / Visa)',
    tags: ['Solutions Architecture', 'Edge Computing', 'MQTT', 'High Availability']
  },
  {
    source: 'LinkedIn Jobs',
    title: 'Solution Architect (API Gateways & Integrations)',
    company: 'BlackStone eIT',
    url: 'https://www.linkedin.com/jobs/view/4482063087/',
    salary: 'Senior Tier (Dubai)',
    location: 'Dubai, UAE (On-site)',
    tags: ['API Gateway', 'OAuth2', 'Event-Driven', 'High-Volume Systems']
  }
];
return linkedInHighPriority.map(j => ({ json: j }));

const statusUpdates = [
  {
    source: 'Email / Inbox Monitor',
    title: 'Persia Fava Gostaresh Co. Infrastructure Collaboration',
    sender: 'Mohammadamin Elyasi (Head of Software Engineering)',
    status: 'Inbound Collaboration Invite Received',
    action: 'Accept & Cross-Post to Dubai Tech Network'
  }
];
return statusUpdates.map(s => ({ json: s }));

const allOpportunities = [
  ...$('RemoteOK Formatter').all().map(i => i.json),
  ...$('Jobicy Formatter').all().map(i => i.json),
  ...$('Bounty Formatter').all().map(i => i.json),
  ...$('LinkedIn Target Pipeline').all().map(i => i.json)
];

const enriched = allOpportunities.map(opp => {
  const encodedCompany = encodeURIComponent(opp.company);
  return {
    ...opp,
    linkedin_company_search: `https://www.linkedin.com/search/results/companies/?keywords=${encodedCompany}`,
    linkedin_cto_search: `https://www.linkedin.com/search/results/people/?keywords=${encodedCompany}%20CTO`,
    linkedin_recruiter_search: `https://www.linkedin.com/search/results/people/?keywords=${encodedCompany}%20Recruiter`
  };
});

return [{ json: { count: enriched.length, opportunities: enriched } }];

const opps = $json.opportunities || [];
const pitched = opps.map(opp => {
  const cleanCompany = opp.company.replace(/[^a-zA-Z0-9 ]/g, '').slice(0, 20);
  const cleanTitle = opp.title.replace(/[^a-zA-Z0-9 ]/g, '').slice(0, 25);

  let note = `Hi, I noticed ${cleanCompany}'s opening for ${cleanTitle}. With 15y architecting telecom & high-throughput payment rails (25k msg/s), I'd value connecting.`;
  if (note.length > 200) note = note.slice(0, 197) + '...';

  return {
    ...opp,
    connection_note_200: note,
    char_count: note.length
  };
});

return [{ json: { target_count: pitched.length, targets: pitched } }];

const targets = $('Surgical 200-Char Connection Drafter').first().json.targets;
const ollamaResponse = $json.response;
const inboxUpdates = $('Email & Status Monitor').all().map(i => i.json);

let message = `🚀 <b>AUTONOMOUS CAREER ENGINE: DAILY INTELLIGENCE DOSSIER</b>\n`;
message += `<i>Date: ${new Date().toLocaleDateString('en-CA')} | Node: Smart-DB Cluster</i>\n\n`;

message += `📬 <b>EMAIL & APPLICATION TRACKER:</b>\n`;
inboxUpdates.forEach(u => {
  message += `• <b>${u.source}</b>: ${u.title}\n  <i>Status:</i> ${u.status}\n  <i>Action:</i> ${u.action}\n\n`;
});

message += `💼 <b>SOURCED OPPORTUNITIES & DECISION MAKERS:</b>\n`;
targets.slice(0, 4).forEach((t, idx) => {
  message += `<b>${idx + 1}. [${t.source}] ${t.title} @ ${t.company}</b>\n`;
  message += `• <i>Location:</i> ${t.location} | <i>Comp:</i> ${t.salary}\n`;
  message += `• <a href="${t.url}">Apply / View Job</a> | <a href="${t.linkedin_cto_search}">Find CTO</a> | <a href="${t.linkedin_company_search}">Company Page</a>\n`;
  message += `• <b>200-Char Connection Note:</b> <code>${t.connection_note_200}</code>\n\n`;
});

message += `📄 <b>ATS COVER LETTER PREVIEW (TOP MATCH: ${targets[0]?.company}):</b>\n`;
const cleanCover = ollamaResponse.slice(0, 700).replace(/<[^>]*>/g, '');
message += `<blockquote>${cleanCover}...</blockquote>\n\n`;
message += `⚡ <i>Full document logged to Smart-DB n8n storage.</i>`;

return [{
  json: {
    telegram_payload: message
  }
}];
